import limited_client as r, numpy as np
for c,ps in [('topview',[(220,187),(380,230),(328,150),(240,197)]),('gripperPOV',[(150,185),(170,285),(230,285)])]:
 o=r.observe(c); K=o['intrinsic']; T=o['camera_to_world'];
 print(c)
 for u,v in ps:
  d=float(o['depth_m'][v,u]); q=np.array([(u-K[0,2])*d/K[0,0],(v-K[1,2])*d/K[1,1],d,1]); w=T@q
  print((u,v),d,w[:3])
