import limited_client as r,numpy as np
for c in ['corner3','topview']:
 o=r.observe(c);a=o['rgb']; d=o['depth_m'];K=o['intrinsic'];T=o['camera_to_world']
 for name,m in [('blue',(a[:,:,2]>100)&(a[:,:,0]<100)&(a[:,:,1]<150)),('green',(a[:,:,1]>180)&(a[:,:,0]<100)&(a[:,:,2]<100))]:
  y,x=np.where(m)
  if len(x):
   pts=[]
   for xx,yy in zip(x,y):
    z=d[yy,xx]; q=np.array([(xx-240)*z/K[0,0],(yy-240)*z/K[1,1],z,1]);pts.append((T@q)[:3])
   print(c,name,'n',len(x),'pix bbox',x.min(),x.max(),y.min(),y.max(),'world med',np.median(pts,axis=0))
